NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Joel'

CHAPTERS = {
    1: {
        1: 'Das Wort Jehovahs, welches geschah an Joel, den Sohn Pethuels,',
        2: 'Höret dies, ihr Ältesten, und nehmt es zu Ohren, alle Bewohner des Landes! Ist solches geschehen in euren Tagen und in den Tagen eurer Väter?',
        3: 'Davon erzählt euren Söhnen, und eure Söhne ihren Söhnen, und deren Söhne dem späteren Geschlecht!',
        4: 'Was die Raupe übrig läßt, frißt die Heuschrecke, und was die Heuschrecke übrig läßt, frißt die Grille, und was die Grille übrig läßt, frißt der Schröter.',
        5: 'Erwachet, ihr Trunkenen, und weint und heult alle Trinker des Weines, ob dem Most, daß er von eurem Munde abgeschnitten wird.',
        6: 'Denn eine Völkerschaft zieht herauf in Mein Land, mächtig und ohne Zahl, seine Zähne sind eines Löwen Zähne, und hat die Backenzähne des alten Löwen.',
        7: 'Meinen Weinstock setzt sie in Verwüstung, zerfetzt Meinen Feigenbaum, blößet ihn bloß, wirft ihn weg und macht seine Reben weiß.',
        8: 'Wehklage, wie die Jungfrau, mit dem Sacke gegürtet über den Gemahl ihrer Jugend.',
        9: 'Abgeschnitten ist Speiseopfer und Trankopfer vom Hause Jehovahs. Die Priester, Jehovahs Diener, trauern.',
        10: 'Verheert ist das Feld, der Boden trauert; denn verheert ist das Korn, der Most ausgetrocknet, das Öl verschmachtet;',
        11: 'Die Ackerleute sind beschämt, die Winzer heulen, ob dem Weizen und ob der Gerste, daß des Feldes Ernte ist verloren;',
        12: 'Der Weinstock ist verdorrt und der Feigenbaum verschmachtet; Granatbaum, auch Palme und Apfelbaum, alle Bäume des Feldes sind verdorrt: denn verdorrt ist die Freude von den Söhnen des Menschen.',
        13: 'Gürtet euch und klagt, ihr Priester, heult, ihr Diener des Altars, kommt und liegt über Nacht in Säcken, ihr Diener meines Gottes: denn Speiseopfer und Trankopfer wird dem Hause eures Gottes vorenthalten.',
        14: 'Heiligt ein Fasten, ruft eine Festversammlung aus, versammelt die Ältesten, alle Bewohner des Landes in das Haus Jehovahs, eures Gottes, und schreit zu Jehovah.',
        15: 'Ach des Tages! denn nahe ist der Tag Jehovahs. Und wie Verheerung von dem Verheerer wird er kommen.',
        16: 'Wird nicht vor unseren Augen die Speise abgeschnitten, vom Hause unseres Gottes Fröhlichkeit und Frohlocken?',
        17: 'Die Körner verschrumpfen unter ihren Schollen. Verwüstet sind die Speicher, eingerissen die Scheunen; denn verdorrt ist das Korn.',
        18: 'Wie seufzt das Vieh! Verwirrt sind der Rinder Triebe; denn keine Weide haben sie, auch die Triebe des Kleinviehs sind verwüstet.',
        19: 'Zu dir, Jehovah, rufe ich; denn Feuer frißt die Auen der Wüste und die Flamme entflammt alle Bäume des Feldes.',
        20: 'Auch das Vieh des Feldes lechzt auf zu Dir; denn ausgetrocknet sind die Flußbette der Wasser, und Feuer frißt die Auen der Wüste.',
    },
    2: {
        1: 'Stoßt in die Posaune in Zion und blaset Lärm auf dem Berg Meiner Heiligkeit! Zittern sollen alle, die im Lande wohnen; denn der Tag Jehovahs kommt, denn er ist nahe.',
        2: 'Ein Tag der Finsternis und des Dunkels, ein Tag der Wolke und der Wolkenmacht, wie die Morgenröte sich ausbreitet über die Berge, ein zahlreich und mächtiges Volk, wie keines war in Ewigkeit, noch nach ihm fürder sein wird in den Jahren von Geschlecht und Geschlecht.',
        3: 'Vor ihm her frißt Feuer und hinter ihm flammt die Flamme. Wie ein Garten Edens ist das Land vor ihm, und hinter ihm ist wie der Wüste Verwüstung; und wird vor ihm auch kein Entkommen sein.',
        4: 'Wie der Rosse Ansehen ist sein Ansehen; und wie die Reiter, so laufen sie.',
        5: 'Wie die Stimme der Streitwagen, so hüpfen sie auf den Häuptern der Berge daher; wie mit der Stimme der Feuerflamme, da sie die Stoppeln frißt; wie ein mächtig Volk, zum Streit geordnet.',
        6: 'Davor kreißen die Völker, alle Angesichter ziehen ihr Wangenrot ein.',
        7: 'Wie Helden laufen sie, wie Männer des Streites steigen sie auf die Mauer hinauf; und jeder Mann geht seinen Weg, nicht wechseln sie ihre Pfade um.',
        8: 'Und kein Mann stößt wider seinen Bruder an; jeder Mann geht auf seiner Bahn. Sie fallen unter den Geschossen und brechen nicht ab.',
        9: 'In der Stadt rennen sie umher, auf der Mauer laufen sie, steigen in die Häuser hinauf und kommen hinein durch die Fenster, wie der Dieb.',
        10: 'Vor ihm zittert die Erde, erbeben die Himmel, Sonne und Mond werden verdunkelt und die Sterne ziehen zusammen ihren Glanz.',
        11: 'Und Jehovah gibt Seine Stimme hervor vor Seiner Streitmacht; denn sehr groß ist Sein Heerlager, denn zahlreich sind die, so Sein Wort tun; denn groß ist der Tag Jehovahs, und sehr furchtbar, und wer kann ihn aushalten?',
        12: 'Aber auch jetzt, spricht Jehovah, kehrt zurück zu Mir mit eurem ganzen Herzen, und mit Fasten und mit Weinen und mit Klagen.',
        13: 'Und zerreißt euer Herz und nicht eure Kleider, und kehrt zurück zu Jehovah, eurem Gott; denn Er ist gnädig und erbarmungsvoll, langmütig und von großer Barmherzigkeit, und reuet Sich des Bösen.',
        14: 'Wer weiß, Er kehrt zurück, und es reut Ihn und Er läßt verbleiben hinter ihm einen Segen: Speiseopfer und Trankopfer für Jehovah, euren Gott.',
        15: 'Stoßt in die Posaune in Zion, heiligt ein Fasten, ruft zu einer Festversammlung!',
        16: 'Versammelt das Volk, heiligt die Versammlung, bringt zusammen die Ältesten, versammelt die Kindlein und die Säuglinge an den Brüsten. Der Bräutigam komme heraus aus seiner Kammer, und die Braut aus ihrem Brautgemach!',
        17: 'Zwischen der Vorhalle und dem Altar weinen die Priester, die Diener Jehovahs, und sprechen: Schone, Jehovah, Deines Volkes und gib Dein Erbe nicht hin der Schmach, daß die Völkerschaften über es herrschen. Warum sollen sie sprechen unter den Völkern: Wo ist ihr Gott?',
        18: 'Und Jehovah eifert für Sein Land, und bemitleidet Sein Volk.',
        19: 'Und Jehovah wird antworten und sprechen zu Seinem Volk: Siehe, Ich sende euch das Korn und den Most und das Öl, auf daß ihr davon euch sättigt, und gebe euch nicht mehr zur Schmach unter den Völkerschaften dahin.',
        20: 'Und den von Mitternacht will Ich von euch entfernen und ihn verstoßen in ein dürres, wüstes Land, sein Angesicht zum östlichen Meer und seine Nachhut an das hintere Meer, und soll sein Gestank aufsteigen und seine Fäulnis aufsteigen; denn er hat sein Tun groß gemacht.',
        21: 'Fürchte dich nicht, o Boden, frohlocke und sei fröhlich, daß Jehovah hat Großes getan!',
        22: 'Fürchtet euch nicht, ihr Vieh des Feldes, denn die Auen der Wüste keimen hervor, denn der Baum trägt seine Frucht, der Feigenbaum und der Weinstock geben ihr Vermögen.',
        23: 'Und ihr Söhne Zions frohlocket und seid fröhlich in Jehovah, eurem Gotte, daß Er euch gibt den Frühregen zur Gerechtigkeit, und für euch herabströmen läßt den Platzregen, den Frühregen und den Spätregen im ersten.',
        24: 'Und die Tennen werden voll von Getreide und die Kufen sollen von Most und Öl überfließen.',
        25: 'Und Ich erstatte euch die Jahre, welche die Heuschrecke, die Grille, der Schröter und die Raupe fraß, Meine große Streitmacht, die unter euch Ich sandte.',
        26: 'Und ihr sollt essen, essen und satt werden, und den Namen Jehovahs, eures Gottes, loben, Der Wunderbares mit euch getan, und Mein Volk soll nicht beschämt werden ewiglich.',
        27: 'Und ihr sollt wissen, daß Ich inmitten Israels bin und Ich Jehovah bin, euer Gott, und keiner mehr. Und Mein Volk soll nicht beschämt werden ewiglich.',
    },
    3: {
        1: 'Und es wird geschehen nach diesem, daß Ich Meinen Geist ausgieße über alles Fleisch, und weissagen werden eure Söhne und eure Töchter; eure Alten werden Träume träumen und eure Jünglinge Gesichte sehen.',
        2: 'Und auch über die Knechte und die Dienstmägde will Ich in jenen Tagen Meinen Geist ausgießen;',
        3: 'Und will Wahrzeichen geben in den Himmeln und auf Erden, Blut und Feuer und Säulen von Rauch.',
        4: 'Die Sonne wird sich in Finsternis und der Mond in Blut verwandeln, bevor der Tag Jehovahs kommt, der große und der furchtbare.',
        5: 'Und geschehen wird, daß jeglicher, der Jehovahs Namen anrufen wird, der wird entrinnen; denn auf dem Berge Zion und in Jerusalem wird ein Entkommen sein, wie Jehovah gesprochen hat, und unter dem Rest, den Jehovah ruft.',
        21: 'Denn siehe, in jenen Tagen und zu selbiger Zeit werde Ich zurückbringen die Gefangenschaft Jehudahs und Jerusalems. Und alle Völkerschaften will Ich zusammenbringen und hinabführen in den Talgrund Jehoschaphat, und rechten allda mit ihnen über Mein Volk und Mein Erbe Israel, daß sie es versprengt haben unter die Völkerschaften und Mein Land geteilt; Und um Mein Volk das Los geworfen, und gegeben den Knaben um eine Buhlerin, und das Mägdlein um Wein verkauft, den sie vertranken. Und ihr auch, Zor und Zidon, und all ihr Kreise des Philisterlandes, was wollt ihr von Mir? Wollt ihr Mir mit Erwiderung vergelten? Und wollt ihr Mir erwidern? Schnell, eilends lasse Ich eure Erwiderung auf euer Haupt zurückfallen. Die ihr Mein Silber und Mein Gold habt genommen, und Mein gutes Begehrtes in eure Tempel habt gebracht; Und Jehudahs Söhne und die Söhne Jerusalems verkauft an Javans Söhne, um sie von ihrer Grenze zu entfernen; Siehe, Ich erwecke sie auf aus dem Orte, dahin ihr sie verkauft, und bringe die Erwiderung zurück auf euer Haupt. Und verkaufe eure Söhne und eure Töchter in die Hand der Söhne Jehudahs, und sie verkaufen sie an die Sabäer, an eine ferne Völkerschaft; denn Jehovah hat es geredet. Rufet dies aus unter die Völkerschaften, heiligt den Streit, weckt auf die Helden, sie sollen herzutreten, heraufziehen alle Männer des Streites! Eure Hacken schmiedet euch zu Schwertern um, zu Speeren eure Winzermesser! Es spreche der Schwache: Ich bin mächtig! Tut euch zusammen und kommt, all ihr Völkerschaften ringsumher, und kommt zusammen allda! Laß Deine Helden hinabziehen, Jehovah. Die Völkerschaften werden auferweckt und kommen herauf in den Talgrund Jehoschaphat: denn allda werde Ich sitzen, zu richten alle Völkerschaften ringsumher. Streckt aus die Sichel, denn die Ernte ist reif. Kommt, zieht hinab; denn voll ist die Kelter, die Kufen fließen über; denn viel ist ihrer Bosheit. Haufen über Haufen im Talgrund der Entscheidung; denn nahe ist der Tag Jehovahs im Talgrund der Entscheidung. Sonne und Mond verdunkeln sich und die Sterne ziehen ihren Glanz zusammen. Und Jehovah brüllt aus Zijon, und aus Jerusalem gibt Er Seine Stimme hervor, und Himmel und Erde erbeben; aber Jehovah ist ein Verlaß Seinem Volk und die Stärke den Söhnen Israels. Und ihr werdet erkennen, daß Ich Jehovah bin, euer Gott, Der auf Zijon wohnt, dem Berge Meiner Heiligkeit; und Jerusalem wird Heiligkeit sein; und Fremde sollen nicht mehr hindurchgehen! Und am selben Tage wird geschehen, daß von Most die Berge triefen und von Milch die Hügel fließen, und alle Flußbette Jehudahs mit Wasser flie-ßen, und vom Hause Jehovahs ein Quell ausgeht und tränkt das Bachtal von Schittim. Ägypten wird zur Verwüstung werden, und Edom zur Wüste der Verwüstung ob der Gewalttat gegen Jehudahs Söhne, in deren Land sie haben unschuldig Blut vergossen. Jehudah aber wird sitzen ewiglich und Jerusalem zu Geschlecht und Geschlecht. Und Ich werde unschuldig erklären ihr Blut, das Ich nicht unschuldig erklärt, und Jehovah wird wohnen in Zijon.',
    },
}
